const sample={folders:[{id:'media',name:'Медиатеория',color:'#b9c6eb'},{id:'art',name:'Искусство и контекст',color:'#e1cdea'},{id:'research',name:'Моё исследование',color:'#cdd6bd'}],materials:[{id:'demo1',title:'Идентичность в сетевом обществе',body:'Как цифровая среда меняет наше представление о себе? Лекция о связях, сообществах и пространстве потоков.',folder:'media',kind:'audio',date:'2026-10-23T12:00:00Z',demo:true,attachments:[]},{id:'demo2',title:'In the zéro form',body:'Цитаты и мысли к чтению. Где заканчивается форма и начинается идея?',folder:'art',kind:'pdf',date:'2026-10-23T11:00:00Z',demo:true,attachments:[]},{id:'demo3',title:'Что значит быть современным?',body:'Современность как отношение ко времени. Вернуться к этой мысли после следующего семинара.',folder:'research',kind:'text',date:'2026-10-23T10:00:00Z',demo:true,attachments:[]},{id:'demo4',title:'Тело как интерфейс',body:'Связать тему цифрового тела с одеждой и самопрезентацией. Найти примеры для исследования.',folder:'inbox',kind:'text',date:'2026-10-22T10:00:00Z',demo:true,attachments:[]}]};
let data;try{data=JSON.parse(localStorage.getItem('jooka-prototype-v1'))}catch{}data ||=structuredClone(sample);
let view='home',tab='collections',editing=null,files=[],objects=[],db;const dialog=$('#composer');
const dbReady=new Promise(resolve=>{try{const r=indexedDB.open('jooka-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>{db=r.result;resolve()};r.onerror=()=>resolve()}catch{resolve()}});
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function save(){try{localStorage.setItem('jooka-prototype-v1',JSON.stringify(data));return true}catch{notify('Не удалось сохранить: проверь свободное место в браузере.');return false}}
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function folderName(id){return id==='inbox'?'Входящие':data.folders.find(f=>f.id===id)?.name||'Входящие'}
function render(){
 $('#folderNav').replaceChildren(...data.folders.map(f=>{const b=el('button','folder-nav'+(view===f.id?' active':''));const dot=el('span','folder-dot');dot.style.background=f.color;b.append(dot,el('span','',f.name));b.onclick=()=>{view=f.id;render()};return b}));
 $$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#inboxCount').textContent=data.materials.filter(m=>m.folder==='inbox').length;
 const home=view==='home',recent=view==='recent';$('#breadcrumb').textContent=home?'Моё пространство':recent?'Моё пространство / Недавнее':'Моё пространство / '+folderName(view);
 $('#heading').textContent=home?'Всё начинается\nс интереса.':recent?'К чему вернуться.':folderName(view);$('#heading').style.whiteSpace='pre-line';$('#eyebrow').textContent=home?'Место для твоего любопытства':recent?'Твои последние материалы':view==='inbox'?'Сохрани сейчас. Разложи потом.':'Твоя коллекция';$('#headingNote').hidden=!home;
 const q=$('#search').value.toLowerCase();$('#collectionGrid').hidden=!home||tab!=='collections'||!!q;$('#collectionsTab').classList.toggle('chosen',tab==='collections');$('#materialsTab').classList.toggle('chosen',tab==='materials');$('#collectionsTab').hidden=!home;
 $('#collectionGrid').replaceChildren(...data.folders.map((f,i)=>{const b=el('button','collection');b.style.setProperty('--tone',f.color);const stack=el('div','stack');stack.setAttribute('aria-hidden','true');const back=el('div','cover back','Мысли, вопросы,\nновые связи.');const middle=el('div','cover middle');const front=el('div','cover front');front.append(el('div','art art-'+i%3),el('div','cover-caption',f.name));stack.append(back,middle,front);const name=el('div','collection-name');const count=data.materials.filter(m=>m.folder===f.id).length;name.append(el('span','',f.name),el('span','count',String(count)));b.append(stack,name,el('p','',count+' '+(count===1?'материал':'материалов')+' · личная коллекция'));b.onclick=()=>{view=f.id;render()};return b}));
 const materials=data.materials.filter(m=>(home||recent||m.folder===view)&&[m.title,m.body,m.source||''].join(' ').toLowerCase().includes(q)).sort((a,b)=>b.date.localeCompare(a.date));
 $('#materialsHeading').textContent=q?'Результаты поиска':home&&tab==='collections'?'Недавно добавленное':'Материалы';$('#materialCount').textContent=materials.length+' в библиотеке';
 $('#materialGrid').replaceChildren(...materials.slice(0,home&&tab==='collections'&&!q?6:undefined).map(m=>{const b=el('button','material');const types={audio:'◉ Аудиолекция',pdf:'▤ Чтение',text:'▱ Заметка',file:'↗ Вложение'};b.append(el('span','material-type',(types[m.kind]||types.text)+(m.demo?' · пример':'')),el('strong','',m.title));if(m.kind==='audio'){const wave=el('div','wave');wave.setAttribute('aria-hidden','true');for(let i=0;i<32;i++){const bar=el('i');bar.style.height=(4+((i*17+7)%23))+'px';wave.append(bar)}b.append(wave)}else b.append(el('p','',m.body||'Открой, чтобы добавить мысли к материалу.'));b.append(el('span','material-meta',folderName(m.folder)));b.onclick=()=>openComposer(m);return b}));
 if(!materials.length)$('#materialGrid').append(el('div','empty',q?'Ничего не нашлось. Попробуй другое слово.':'Здесь пока тихо. Добавь первый материал.'));
}
function resetFiles(){objects.forEach(u=>URL.revokeObjectURL(u));objects=[]}
async function openComposer(m){editing=m?.id||null;files=structuredClone(m?.attachments||[]);resetFiles();$('#dialogLabel').textContent=m?(m.demo?'Пример материала · можно редактировать':'Твой материал'):'Новый материал';$('#title').value=m?.title||'';$('#body').value=m?.body||'';$('#source').value=m?.source||'';$('#sourceWrap').hidden=!m?.source;$('#recordPanel').hidden=true;$('#composeStatus').textContent='';$('#files').value='';$('#folder').replaceChildren(...[{id:'inbox',name:'Входящие'},...data.folders].map(f=>{const o=el('option','',f.name);o.value=f.id;return o}));$('#folder').value=m?.folder||(data.folders.some(f=>f.id===view)?view:'inbox');renderFiles();dialog.showModal();setTimeout(()=>$('#title').focus(),0)}
async function renderFiles(){await dbReady;const container=$('#attachments');container.replaceChildren();for(const file of files){const row=el('div','attachment');row.append(el('span','',file.name+' · '+Math.max(1,Math.round(file.size/1024))+' КБ'));const actions=el('div');if(file.pending){actions.append(el('span','','Готов к сохранению'))}else if(db){const blob=await new Promise(resolve=>{const r=db.transaction('files').objectStore('files').get(file.id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null)});if(blob){const u=URL.createObjectURL(blob);objects.push(u);const a=el('a','','Скачать');a.href=u;a.download=file.name;actions.append(a)}}const remove=el('button','',' ×');remove.type='button';remove.setAttribute('aria-label','Убрать '+file.name);remove.onclick=()=>{files=files.filter(f=>f.id!==file.id);renderFiles()};actions.append(remove);row.append(actions);container.append(row)}}
function addFiles(list){for(const f of list){if(f.size>50*1024*1024){notify('В прототипе размер одного файла — до 50 МБ.');continue}files.push({id:crypto.randomUUID(),name:f.name,size:f.size,type:f.type,pending:f})}renderFiles()}
$('#files').onchange=e=>addFiles(e.target.files);const drop=$('#dropzone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('over')};drop.ondragleave=()=>drop.classList.remove('over');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('over');addFiles(e.dataTransfer.files)};
$('#composeForm').onsubmit=async e=>{e.preventDefault();const title=$('#title').value.trim(),body=$('#body').value.trim();if(!title&&!body&&!files.length){$('#composeStatus').textContent='Добавь текст или файл, чтобы сохранить материал.';return}const submit=e.submitter;submit.disabled=true;await dbReady;try{for(const f of files.filter(f=>f.pending)){if(!db)throw Error('Хранение вложений недоступно в этом браузере.');await new Promise((resolve,reject)=>{const t=db.transaction('files','readwrite');t.objectStore('files').put(f.pending,f.id);t.oncomplete=resolve;t.onerror=()=>reject(Error('Не удалось сохранить вложение. Возможно, закончилось место.'))})}
 const prev=data.materials.find(m=>m.id===editing);const first=files[0];const kind=first?(first.type?.startsWith('audio/')||first.type?.startsWith('video/')?'audio':first.type==='application/pdf'?'pdf':'file'):'text';const material={id:editing||crypto.randomUUID(),title:title||first?.name||'Без названия',body,source:$('#source').value,folder:$('#folder').value,kind:prev?.kind||kind,date:new Date().toISOString(),attachments:files.map(({pending,...f})=>f),demo:false};const next={...data,materials:editing?data.materials.map(m=>m.id===editing?material:m):[material,...data.materials]};const old=data;data=next;if(!save()){data=old;throw Error('Текст не сохранён. Попробуй экспортировать его вручную.')}dialog.close();resetFiles();render();notify('Материал сохранён в «'+folderName(material.folder)+'»')}catch(err){$('#composeStatus').textContent=err.message}finally{submit.disabled=false}};
$('#add').onclick=()=>openComposer();$('#close').onclick=()=>dialog.close();$('#record').onclick=()=>$('#recordPanel').hidden=false;$('#dismissRecord').onclick=()=>$('#recordPanel').hidden=true;$('#link').onclick=()=>{$('#sourceWrap').hidden=false;$('#source').focus()};dialog.addEventListener('close',resetFiles);
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});$('.logo').onclick=e=>{e.preventDefault();view='home';render()};$('#search').oninput=render;$('#collectionsTab').onclick=()=>{tab='collections';render()};$('#materialsTab').onclick=()=>{tab='materials';render()};$('#help').onclick=()=>notify('Дизайн-прототип: материалы сохраняются в этом браузере. AI, запись и Moodle пока не подключены.');$('#folderAdd').onclick=()=>{$('#folderName').value='';$('#collectionDialog').showModal();$('#folderName').focus()};$('#closeFolder').onclick=()=>$('#collectionDialog').close();$('#folderForm').onsubmit=e=>{e.preventDefault();const name=$('#folderName').value.trim();if(!name)return;data.folders.push({id:crypto.randomUUID(),name,color:['#cdd6bd','#e1cdea','#b9c6eb','#ebd0b9'][data.folders.length%4]});if(save()){$('#collectionDialog').close();render();notify('Коллекция создана')}};
for(const d of $$('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
